def bal(s):
	st = []
	for i in s:
		if i == '(':
			st.append(i)
		elif st == []:
			return -1
		else:
			st.pop()
	return st != []

def fun(s, k):
	n = len(s)
	for i in range(n - 1):
		if s[i] == ')' and s[i + 1] == '(':
			k -= 1
			if k == 0:
				return i
	if k == 1:
		return n - 1
	k -= 1
	for i in range(n - 1, 0, -1):
		if s[i] == '(' and s[i - 1] == ')':
			k -= 1
			if k == 0:
				return i
	if k == 1:
		return 0
	return -1
for _ in range(int(input())):
	s = input()
	k = int(input())
	if bal(s):
		if k == 1:
			print(s)
		else:
			print(-1)
	else:
		i = fun(s, k)
		if i == -1:
			print(-1)
		else:
			s = s[:i] + s[i + 1:]
			print(s)
